execute-script.function:
{
	name = $p.get(`tl.demo.projectManagement:ProjectScope#name`);
	milestones = $p.get(`tl.demo.projectManagement:ProjectScope#milestones`);
	tickets = $p.get(`tl.demo.projectManagement:ProjectScope#tickets`);
	milestoneOf = t -> $t.get(`tl.demo.projectManagement:Ticket#milestone`);
	dueOf = m -> if($m == null, null, $m.get(`tl.demo.projectManagement:Milestone#dueDate`));
	isApproved = m -> $m != null && $m.get(`tl.demo.projectManagement:Milestone#approved`) == true;
	nameOf = m -> if($m == null, "–", $m.get(`tl.demo.projectManagement:Milestone#name`));
	formatDate = d -> if($d == null, "–", dateFormat("dd.MM.yyyy").format($d));

	// A ticket is done, when its milestone is approved.
	open = $tickets.filter(t -> !$isApproved($milestoneOf($t)));
	done = $tickets.filter(t -> $isApproved($milestoneOf($t)));
	approved = $milestones.filter(m -> $isApproved($m));
	next = $milestones.filter(m -> !$isApproved($m)).firstElement();

	// The urgency of an open ticket follows from the due date of its milestone.
	urgencyOf = t -> {
		due = $dueOf($milestoneOf($t));
		switch {
			$due == null: ["none", #('no date'@en, 'ohne Termin'@de).localize()];
			$due < today(): ["high", #('overdue'@en, 'überfällig'@de).localize()];
			$due < today().toSystemCalendar().withDayAdded(14).toDate(): ["medium", #('due soon'@en, 'bald fällig'@de).localize()];
			default: ["low", #('on schedule'@en, 'im Plan'@de).localize()];
		}
	};
	urgency = t -> {
		level = $urgencyOf($t);
		pptRating($level[0], $level[1]);
	};

	header = h -> pptCell($h, fill: "topicA", color: "inverse", bold: true);
	numberOf = t -> $t.get(`tl.demo.projectManagement:Ticket#number`);
	labelOf = t -> if($numberOf($t) == null, "–", toString("#", $numberOf($t)));
	assigneeOf = t -> {
		assignee = $t.get(`tl.demo.projectManagement:Ticket#assignee`);
		if($assignee == null, "–", $assignee.get(`Contacts:PersonContact#fullName`));
	};
	openByNumber = $open.sort(comparator(t -> $numberOf($t)));
	ticketRows = $openByNumber.map(t -> [
		$labelOf($t),
		$t.get(`tl.demo.projectManagement:Ticket#title`),
		$nameOf($milestoneOf($t)),
		$formatDate($dueOf($milestoneOf($t))),
		$assigneeOf($t),
		$urgency($t)
	]);

	titleSlide = pptTitle($name, #('Status report of {0}'@en, 'Statusbericht vom {0}'@de).fill($formatDate(today())).localize(),
		notes: #('Status of the project at a glance: key figures, schedule and open tickets.'@en,
			'Der Stand des Projekts im Überblick: Kennzahlen, Zeitplan und offene Tickets.'@de).localize());

	agendaSlide = pptAgenda([
			#('Key figures'@en, 'Kennzahlen'@de).localize(),
			#('Schedule'@en, 'Zeitplan'@de).localize(),
			#('Tickets per milestone'@en, 'Tickets je Meilenstein'@de).localize(),
			#('Open tickets'@en, 'Offene Tickets'@de).localize()
		],
		notes: #('The report follows these four topics.'@en, 'Der Bericht folgt diesen vier Themen.'@de).localize());

	figuresSlide = pptContent(#('Key figures'@en, 'Kennzahlen'@de).localize(),
		$p.get(`tl.demo.projectManagement:ProjectScope#description`), [
			pptRow([
				pptStat($open.size(), #('open tickets'@en, 'offene Tickets'@de).localize(),
					#('in milestones not yet approved'@en, 'in nicht abgenommenen Meilensteinen'@de).localize(), role: "risk"),
				pptStat($done.size(), #('done tickets'@en, 'erledigte Tickets'@de).localize(),
					#('in approved milestones'@en, 'in abgenommenen Meilensteinen'@de).localize(), role: "done"),
				pptStat($milestones.size(), #('milestones'@en, 'Meilensteine'@de).localize(),
					#('{0} of them approved'@en, 'davon {0} abgenommen'@de).fill($approved.size()).localize(), role: "topicA")
			], height: "auto"),
			pptBanner(if($open.isEmpty(),
				#('All tickets are done.'@en, 'Alle Tickets sind erledigt.'@de).localize(),
				#('{0} of {1} tickets are still open.'@en, '{0} von {1} Tickets sind noch offen.'@de)
					.fill($open.size(), $tickets.size()).localize()),
				role: if($open.isEmpty(), "done", "topicA"))
		],
		notes: #('Open and done tickets as well as the milestones of the project. A ticket counts as done, when its milestone is approved.'@en,
			'Offene und erledigte Tickets sowie die Meilensteine des Projekts. Ein Ticket gilt als erledigt, wenn sein Meilenstein abgenommen ist.'@de).localize());

	scheduleSlide = pptContent(#('Schedule'@en, 'Zeitplan'@de).localize(), null,
		if($milestones.isEmpty(),
			pptBanner(#('The project has no milestones yet.'@en, 'Das Projekt hat noch keine Meilensteine.'@de).localize(), role: "muted"),
			[
				pptTimeline($milestones.map(m -> [
					$formatDate($dueOf($m)),
					$nameOf($m),
					if($isApproved($m), #('approved'@en, 'abgenommen'@de).localize(), #('open'@en, 'offen'@de).localize()),
					if($isApproved($m), "done", "topicA")
				])),
				if($next == null,
					pptBanner(#('All milestones are approved.'@en, 'Alle Meilensteine sind abgenommen.'@de).localize(), role: "done"),
					pptBanner(#('Next milestone: {0}, due {1}'@en, 'Nächster Meilenstein: {0}, fällig {1}'@de)
						.fill($nameOf($next), $formatDate($dueOf($next))).localize()))
			]),
		notes: #('The milestones in their planned order with their due date; green milestones are approved.'@en,
			'Die Meilensteine in ihrer geplanten Reihenfolge mit Fälligkeitsdatum; grüne Meilensteine sind abgenommen.'@de).localize());

	chartSlide = pptContent(#('Tickets per milestone'@en, 'Tickets je Meilenstein'@de).localize(), null,
		if($milestones.isEmpty(),
			pptBanner(#('The project has no milestones yet.'@en, 'Das Projekt hat noch keine Meilensteine.'@de).localize(), role: "muted"),
			pptColumnChart($milestones.map(m -> $nameOf($m)), [
				pptSeries(#('open'@en, 'offen'@de).localize(),
					$milestones.map(m -> $open.filter(t -> $milestoneOf($t) == $m).size()), "risk"),
				pptSeries(#('done'@en, 'erledigt'@de).localize(),
					$milestones.map(m -> $done.filter(t -> $milestoneOf($t) == $m).size()), "done")
			], stacked: true)),
		notes: #('The chart is a real PowerPoint chart; its data can be edited in PowerPoint.'@en,
			'Das Diagramm ist ein echtes PowerPoint-Diagramm; seine Daten lassen sich in PowerPoint bearbeiten.'@de).localize());

	ticketSlide = pptContent(#('Open tickets'@en, 'Offene Tickets'@de).localize(), null,
		if($open.isEmpty(),
			pptBanner(#('There are no open tickets.'@en, 'Es gibt keine offenen Tickets.'@de).localize(), role: "done"),
			pptTable(concat([[
					$header(#('No.'@en, 'Nr.'@de).localize()),
					$header(#('Title'@en, 'Titel'@de).localize()),
					$header(#('Milestone'@en, 'Meilenstein'@de).localize()),
					$header(#('Due'@en, 'Fällig'@de).localize()),
					$header(#('Assignee'@en, 'Bearbeiter'@de).localize()),
					$header(#('Urgency'@en, 'Dringlichkeit'@de).localize())
				]], $ticketRows),
				headerRows: 1, columnWeights: [1, 6, 2, 1.6, 2.4, 2])),
		notes: #('The open tickets with the due date of their milestone. A long list continues on further slides.'@en,
			'Die offenen Tickets mit dem Fälligkeitsdatum ihres Meilensteins. Eine lange Liste wird auf weiteren Folien fortgesetzt.'@de).localize());

	// One slide per open ticket with its description; a long description continues on further slides.
	detailSlides = $openByNumber.map(t -> {
		description = $t.get(`tl.demo.projectManagement:Ticket#description`);
		pptContent(toString($labelOf($t), " ", $t.get(`tl.demo.projectManagement:Ticket#title`)),
			toString($nameOf($milestoneOf($t)), " · ", $assigneeOf($t)),
			if($description == null || toString($description).trim().isEmpty(),
				pptTextBox(#('No description.'@en, 'Keine Beschreibung.'@de).localize(), color: "muted", italic: true),
				pptHtml($description)),
			notes: #('Due: {0}, {1}.'@en, 'Fällig: {0}, {1}.'@de)
				.fill($formatDate($dueOf($milestoneOf($t))), $urgencyOf($t)[1]).localize());
	});

	pptDeck($p.get(`tl.demo.projectManagement:ProjectScope#reportTemplate`),
		concat([$titleSlide, $agendaSlide, $figuresSlide, $scheduleSlide, $chartSlide, $ticketSlide], $detailSlides),
		footer: #('Status report {0}'@en, 'Statusbericht {0}'@de).fill($name).localize(),
		name: toString($name, ".pptx"))
}
